import com.comsol.model.*; import java.util.*; public final class AxisProbe {public static Object run(Model model, Map<String,Object> args) {Map<String,Object> result=new LinkedHashMap<>();Map<String,Object> datasets=new LinkedHashMap<>(); for(String dt:model.result().dataset().tags()) {Map<String,Object> d=new LinkedHashMap<>(); d.put("type",model.result().dataset(dt).getType());try { d.put("solution",model.result().dataset(dt).getString("solution")); } catch(Exception e) {} datasets.put(dt,d); }result.put("datasets",datasets); for(String tag:model.sol().tags()) {Map<String,Object> out=new LinkedHashMap<>(); SolverSequence sequence=model.sol(tag); SolutionInfo info=sequence.getSolutioninfo();try { out.put("outer", info.getOuterSolnum()); } catch(Exception e) { out.put("outer_ERROR", e.toString()); }try { out.put("pairs_empty_filter", info.getSolnums(new String[]{})); } catch(Exception e) { out.put("pairs_empty_filter_ERROR", e.toString()); }try { out.put("pairs_t_filter", info.getSolnums(new String[]{"t"})); } catch(Exception e) { out.put("pairs_t_filter_ERROR", e.toString()); }try { out.put("inner_1_strict", info.getSolnum(1, true)); } catch(Exception e) { out.put("inner_1_strict_ERROR", e.toString()); }try { out.put("inner_1_nonstrict", info.getSolnum(1, false)); } catch(Exception e) { out.put("inner_1_nonstrict_ERROR", e.toString()); }try { out.put("inner_0_strict", info.getSolnum(0, true)); } catch(Exception e) { out.put("inner_0_strict_ERROR", e.toString()); }try { out.put("levels", info.getLevelNames()); } catch(Exception e) { out.put("levels_ERROR", e.toString()); }try { out.put("pnames_11", info.getPNames(new int[][]{{1,1}})); } catch(Exception e) { out.put("pnames_11_ERROR", e.toString()); }try { out.put("pvals_11", info.getPvals(new int[][]{{1,1}})); } catch(Exception e) { out.put("pvals_11_ERROR", e.toString()); }try { out.put("units_11", info.getUnits(new int[][]{{1,1}})); } catch(Exception e) { out.put("units_11_ERROR", e.toString()); }try { out.put("solver_pnames", sequence.getPNames()); } catch(Exception e) { out.put("solver_pnames_ERROR", e.toString()); }try { out.put("solver_pvals", sequence.getPVals()); } catch(Exception e) { out.put("solver_pvals_ERROR", e.toString()); }try { out.put("solver_pvals_1", sequence.getPVals(1)); } catch(Exception e) { out.put("solver_pvals_1_ERROR", e.toString()); }try { out.put("solver_type", sequence.getType()); } catch(Exception e) { out.put("solver_type_ERROR", e.toString()); }try { out.put("info_unit_t", info.getUnit("t")); } catch(Exception e) { out.put("info_unit_t_ERROR", e.toString()); }try { out.put("info_sol_1", info.getSol(1)); } catch(Exception e) { out.put("info_sol_1_ERROR", e.toString()); }try { out.put("info_solver_1", info.getSolverSequence(1)); } catch(Exception e) { out.put("info_solver_1_ERROR", e.toString()); }result.put(tag,out); } return result; }}